const NAVY = "#1A2B48";
const ORANGE = "#F56C43";
const PEACH = "#FFF5F0";
const PEACH_BORDER = "#FDE4D8";

function swatchFromColor(group) {
  const code = group?.color_code || group?.color?.code || group?.code;
  if (code && /^#?[0-9a-f]{3,8}$/i.test(String(code).trim())) {
    return String(code).startsWith("#") ? code : `#${code}`;
  }
  const name = String(group?.color_name || group?.color?.name || group?.name || "").toLowerCase();
  const map = {
    black: "#111827",
    white: "#F9FAFB",
    blue: "#2563EB",
    "sky blue": "#87CEEB",
    navy: "#1A2B48",
    red: "#DC2626",
    green: "#16A34A",
    grey: "#6B7280",
    gray: "#6B7280",
    pink: "#EC4899",
    beige: "#D4B896",
    brown: "#92400E",
    yellow: "#EAB308",
    orange: "#F56C43",
  };
  if (map[name]) return map[name];
  const hit = Object.keys(map).find((k) => name.includes(k));
  return hit ? map[hit] : "#D1D5DB";
}

export const REVIEW_SECTIONS = [
  { id: "product_info", label: "Product Information", Icon: Package },
  { id: "key_features", label: "Key Features", Icon: ListChecks },
  { id: "description", label: "Product Description", Icon: FileText },
  { id: "specifications", label: "Specifications", Icon: SlidersHorizontal },
  { id: "whats_in_box", label: "What's in the Box", Icon: Gift },
  { id: "pricing", label: "Pricing & Inventory", Icon: IndianRupee },
  { id: "seo", label: "SEO Information", Icon: Search },
  { id: "shipping", label: "Shipping Details", Icon: Truck },
  { id: "benefits", label: "Benefits", Icon: Star },
  { id: "size_chart", label: "Size Chart", Icon: Ruler },
];

function inr(n) {
  const v = Number(n);
  if (!Number.isFinite(v) || v <= 0) return "₹ —";
  return `₹${v.toLocaleString("en-IN", { maximumFractionDigits: 0 })}`;
}

