export function AiReviewNav({
  sections,
  reviewSection,
  setReviewSection,
  isAi,
  isDirty,
}) {
  return (
    <nav className="bg-white rounded-2xl border border-[#F1F5F9] p-2 space-y-0.5">
      {sections.map((s) => {
        const active = reviewSection === s.id;
        const Icon = s.Icon || Box;
        return (
          <button
            key={s.id}
            type="button"
            onClick={() => setReviewSection(s.id)}
            className="w-full text-left px-2.5 py-2.5 rounded-xl text-[13px] flex items-center gap-2.5 transition-colors hover:bg-[#FFF8F4]"
            style={
              active
                ? {
                    backgroundColor: PEACH,
                    color: ORANGE,
                    fontWeight: 700,
                    boxShadow: `inset 3px 0 0 ${ORANGE}`,
                  }
                : { color: NAVY, fontWeight: 500 }
            }
          >
            <span
              className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0"
              style={{
                backgroundColor: active ? "#fff" : "#F8FAFC",
                color: active ? ORANGE : "#94A3B8",
              }}
            >
              <Icon className="w-4 h-4" strokeWidth={2} />
            </span>
            <span className="flex-1 min-w-0 leading-tight">{s.label}</span>
            <span className="flex flex-col items-end gap-0.5 shrink-0">
              {isDirty?.(s.id) ? (
                <span className="text-[9px] font-semibold bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded-full">
                  Edited
                </span>
              ) : null}
              {isAi?.(s.id) ? (
                <span
                  className="w-1.5 h-1.5 rounded-full"
                  style={{ backgroundColor: "#22C55E" }}
                />
              ) : null}
            </span>
          </button>
        );
      })}
    </nav>
  );
}

