export function StorefrontPreviewCard({ state, previewUrl, settlement }) {
  const groups = (state?.colorGroups || []).filter((g) => g.color_id || g.color?.id);
  const [colorKey, setColorKey] = useState(() =>
    String(state?.color_id || groups[0]?.color_id || groups[0]?.color?.id || ""),
  );

  useEffect(() => {
    if (!groups.length) {
      if (colorKey) setColorKey("");
      return;
    }
    const ids = new Set(groups.map((g) => String(g.color_id || g.color?.id)));
    if (colorKey && ids.has(String(colorKey))) return;
    const preferred = String(state?.color_id || groups[0].color_id || groups[0].color?.id || "");
    setColorKey(preferred);
  }, [groups, state?.color_id, colorKey]);

  const selectedGroup = useMemo(() => {
    if (!groups.length) return null;
    return groups.find((g) => String(g.color_id || g.color?.id) === String(colorKey)) || groups[0];
  }, [groups, colorKey]);

  const sizeChips = (selectedGroup?.sizes || [])
    .map((s) => s.size?.name || "")
    .filter(Boolean);
  const uniqueSizes = [...new Set(sizeChips)];

  const colorPreview = useMemo(
    () => selectedColorPreviewSrc(selectedGroup, state?.sizeMedia),
    [selectedGroup, state?.sizeMedia],
  );

  const row = selectedGroup?.sizes?.find((s) => Number(s.discounted_price) > 0) || selectedGroup?.sizes?.[0];
  const sale = Number(row?.discounted_price || settlement?.sale || state?.discounted_price) || 0;
  const mrp = Number(row?.original_price || settlement?.mrp || state?.original_price) || 0;
  const listingPrice = Number(settlement?.listingPrice) || 0;
  const off =
    mrp > 0 && sale > 0 && mrp > sale
      ? Math.round(((mrp - sale) / mrp) * 100)
      : settlement?.discountPct != null && Number(settlement.discountPct) > 0
        ? Number(settlement.discountPct)
        : mrp > 0 && listingPrice > 0 && mrp > listingPrice
          ? Math.round(((mrp - listingPrice) / mrp) * 100)
          : 0;
  const title = state?.name || "Product name";
  const firstColorId = String(groups[0]?.color_id || groups[0]?.color?.id || "");
  const selectedColorId = String(selectedGroup?.color_id || selectedGroup?.color?.id || "");
  const mirrorFirst =
    selectedColorId &&
    selectedColorId === firstColorId &&
    firstColorMirrorsPrimaryGallery(state, selectedGroup);
  const shownUrl = mirrorFirst
    ? previewUrl || colorPreview
    : colorPreview || (!groups.length ? previewUrl : "");
  return (
    <div
      className="bg-white rounded-2xl overflow-hidden"
      style={{ border: "1px solid #F1F5F9", boxShadow: "0 8px 24px rgba(26, 43, 72, 0.06)" }}
    >
      <p className="px-2 pt-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">
        Preview on IERADA
      </p>
      <div className="relative w-full aspect-[3/4] bg-[#F3F4F6] mt-1 overflow-hidden">
        {shownUrl ? (
          <img
            key={shownUrl}
            src={shownUrl}
            alt={selectedGroup?.color_name || "Variant preview"}
            className="absolute inset-0 w-full h-full object-cover object-center"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <Package className="w-10 h-10 text-slate-300" strokeWidth={1.25} />
          </div>
        )}
        <button
          type="button"
          tabIndex={-1}
          className="absolute top-2.5 right-2.5 w-8 h-8 rounded-full bg-white/90 flex items-center justify-center shadow-sm"
          aria-label="Wishlist preview"
        >
          <Heart className="w-4 h-4 text-slate-400" />
        </button>
      </div>
      <div className="px-3.5 py-3">
        {groups.length ? (
          <div className="flex flex-wrap gap-1.5 mb-2">
            {groups.map((g) => {
              const id = String(g.color_id || g.color?.id);
              const active = String(selectedGroup?.color_id || selectedGroup?.color?.id) === id;
              return (
                <button
                  key={id}
                  type="button"
                  title={g.color_name}
                  onClick={() => setColorKey(id)}
                  className="w-5 h-5 rounded-full"
                  style={{
                    backgroundColor: swatchFromColor(g),
                    boxShadow: active ? `0 0 0 2px ${ORANGE}` : "0 0 0 1px #E5E7EB",
                  }}
                />
              );
            })}
          </div>
        ) : null}
        {uniqueSizes.length ? (
          <div className="flex flex-wrap gap-1 mb-2">
            {uniqueSizes.map((name) => (
              <span
                key={name}
                className="min-w-[28px] px-1.5 py-0.5 rounded text-[10px] font-semibold text-center"
                style={{ border: "1px solid #E5E7EB", color: NAVY }}
              >
                {name}
              </span>
            ))}
          </div>
        ) : null}
        <p className="text-[13px] font-semibold line-clamp-2 leading-snug" style={{ color: NAVY }}>
          {title}
        </p>
        <div className="flex items-baseline gap-2 mt-1.5 flex-wrap">
          <span className="text-[20px] font-extrabold" style={{ color: NAVY }}>
            {sale > 0 ? inr(sale) : inr(mrp)}
          </span>
          {mrp > sale && sale > 0 ? (
            <span className="text-[13px] text-slate-400 line-through">{inr(mrp)}</span>
          ) : null}
          {off > 0 ? (
            <span className="text-[12px] font-bold text-emerald-600">{off}% OFF</span>
          ) : null}
        </div>
        <p className="text-[12px] text-slate-500 flex items-center gap-1 mt-1.5">
          {[0, 1, 2, 3, 4].map((i) => (
            <Star
              key={i}
              className={`w-3.5 h-3.5 ${i < 4 ? "text-amber-400 fill-amber-400" : "text-amber-300 fill-amber-200"}`}
            />
          ))}
          <span className="text-slate-400 ml-0.5">(128)</span>
        </p>
      </div>
    </div>
  );
}

function money(n) {
  const v = Number(n) || 0;
  const rounded = Math.round(v * 100) / 100;
  if (Number.isInteger(rounded)) return `₹${rounded}`;
  return `₹${rounded.toFixed(2)}`;
}

export function BankSettlementSummary({ state, settlement }) {
  const rows = [
    ["MRP", money(settlement?.mrp)],
    ["Sale", money(settlement?.sale)],
    ...(settlement?.size_labels
      ? [["Size", settlement.size_labels]]
      : state?.size_ids?.length
        ? [["Size", `${state.size_ids.length} selected`]]
        : []),
    ...(settlement?.color_label
      ? [["Colour", settlement.color_label]]
      : state?.color_name
        ? [["Colour", state.color_name]]
        : []),
    ["Discount %", `${settlement?.discountPct || 0}%`],
    ["GST breakup", money(settlement?.gstAmount)],
    ["TDS (2%)", money(settlement?.tds)],
    ["Shipping (Customer)", money(settlement?.shipping)],
    ["Platform fee", money(settlement?.platformFee)],
  ];
  return (
    <div
      className="bg-white rounded-[10px] px-2.5 py-2"
      style={{ border: "1px solid #F1F5F9", boxShadow: "0 8px 24px rgba(26, 43, 72, 0.06)" }}
    >
      <h3 className="text-[12px] font-bold mb-1.5" style={{ color: NAVY }}>
        Bank Settlement Summary
      </h3>
      <div className="space-y-0.5">
        {rows.map(([label, value]) => (
          <div key={label} className="flex justify-between text-[11px] leading-tight text-slate-500">
            <span>{label}</span>
            <span className="text-slate-700 tabular-nums">{value}</span>
          </div>
        ))}
      </div>
      <div
        className="mt-1.5 flex justify-between items-center rounded-md px-2 py-1 text-[11.5px] font-bold"
        style={{ backgroundColor: "#FFF5F0", border: "1px solid #FBD38D", color: ORANGE }}
      >
        <span>Listing Price</span>
        <span>{money(settlement?.listingPrice)}</span>
      </div>
      <div
        className="mt-1 flex justify-between items-center rounded-md px-2 py-1 text-[11.5px] font-bold"
        style={{ backgroundColor: "#F0FFF4", border: "1px solid #C6F6D5", color: "#276749" }}
      >
        <span>You Earn</span>
        <span>{money(settlement?.youEarn)}</span>
      </div>
      <p className="mt-1.5 text-[9px] italic text-slate-400 leading-snug">
        Rates are provisional until Ops confirms commission/TDS rules.
      </p>
    </div>
  );
}
